fn load(path: Text) -> Text uses fs or fail {
    return try read_file(path)
}

fn show(line: Text) -> Text uses fs {
    if file_exists(line) {
        return "> " + line
    }
    return line
}

fn main() uses io, fs {
    for a in args() {
        check load(a) {
            ok text {
                print(show(text))
            }
            fail why {
                print(why)
            }
        }
    }
}
